SGC_MAINTENANCE_SOURCE
    , true, 512, JSON_THROW_ON_ERROR));

    $maintenanceCategories = [
        'HERRAMIENTA' => 'Herramientas',
        'ECP' => 'ECP / PCE',
        'UNIDAD' => 'Unidades',
    ];

    $maintenanceTypes = [
        'FORMATO' => 'Formatos capturados',
        'MANTENIMIENTO' => 'Evidencias / PDFs',
    ];

    $maintenanceYears = $maintenanceAll->pluck('year')
        ->filter()
        ->merge(['2026', '2025', '2024'])
        ->unique()
        ->sortDesc()
        ->values();

    $maintenanceStatuses = $maintenanceAll->pluck('status')
        ->unique()
        ->sort()
        ->values();

    // Aceptamos solamente valores de texto, incluidos en nuestras opciones.
    $maintenanceQuery = static function (string $key, string $default = 'TODOS'): string {
        $value = request()->query($key, $default);

        return is_string($value) ? trim($value) : $default;
    };

    $maintenanceFilters = [
        'year' => $maintenanceQuery('year'),
        'category' => $maintenanceQuery('category'),
        'type' => $maintenanceQuery('type'),
        'status' => $maintenanceQuery('status'),
        'q' => $maintenanceQuery('q', ''),
    ];

    $maintenanceAllowed = [
        'year' => $maintenanceYears->map(static fn ($year) => (string) $year)->all(),
        'category' => array_keys($maintenanceCategories),
        'type' => array_keys($maintenanceTypes),
        'status' => $maintenanceStatuses->all(),
    ];

    foreach ($maintenanceAllowed as $key => $values) {
        if (!in_array($maintenanceFilters[$key], $values, true)) {
            $maintenanceFilters[$key] = 'TODOS';
        }
    }

    $maintenanceNormalize = static fn (string $text): string =>
        \Illuminate\Support\Str::lower(\Illuminate\Support\Str::ascii($text));

    $maintenanceNeedle = $maintenanceNormalize($maintenanceFilters['q']);

    // El JS general envía estos filtros y recibe este mismo hijo actualizado.
    $maintenanceRecords = $maintenanceAll->filter(
        static function (array $record) use ($maintenanceFilters, $maintenanceNeedle, $maintenanceNormalize): bool {
            if (
                $maintenanceFilters['category'] !== 'TODOS' &&
                $record['category'] !== $maintenanceFilters['category']
            ) {
                return false;
            }

            if (
                $maintenanceFilters['year'] !== 'TODOS' &&
                $record['year'] !== $maintenanceFilters['year']
            ) {
                return false;
            }

            if (
                $maintenanceFilters['status'] !== 'TODOS' &&
                $record['status'] !== $maintenanceFilters['status']
            ) {
                return false;
            }

            if ($maintenanceFilters['type'] === 'FORMATO' && $record['type'] !== 'FORMATO') {
                return false;
            }

            // Evidencias / PDFs agrupa mantenimientos, evidencias y certificaciones.
            if ($maintenanceFilters['type'] === 'MANTENIMIENTO' && $record['type'] === 'FORMATO') {
                return false;
            }

            if ($maintenanceNeedle !== '') {
                $searchText = implode(' ', [
                    $record['category'],
                    $record['type'],
                    $record['date'],
                    $record['code'],
                    $record['asset'],
                    $record['serial_plate'],
                    $record['meter_text'],
                    $record['format_code'],
                    $record['description'],
                    $record['status'],
                    rawurldecode($record['file_url'] ?? ''),
                ]);

                if (!str_contains($maintenanceNormalize($searchText), $maintenanceNeedle)) {
                    return false;
                }
            }

            return true;
        }
    )->values();

    // Totales de la colección completa; Mostrados refleja los filtros actuales.
    $maintenanceSummary = [
        'total' => $maintenanceAll->count(),
        'tools' => $maintenanceAll->where('category', 'HERRAMIENTA')->count(),
        'ecp' => $maintenanceAll->where('category', 'ECP')->count(),
        'units' => $maintenanceAll->where('category', 'UNIDAD')->count(),
        'formats' => $maintenanceAll->where('type', 'FORMATO')->count(),
        'shown' => $maintenanceRecords->count(),
    ];

    $maintenanceCategoryTitle = $maintenanceCategories[$maintenanceFilters['category']] ?? 'Todas las categorías';
